Lemma addmul_inv : forall acc pw c s A C, toZ pw = 2 ^ s mod 2 ^ 63 -> toZ acc = A mod 2 ^ 63 -> toZ c = C ->
  toZ (PrimInt63.add acc (PrimInt63.mul pw c)) = (A + 2 ^ s * C) mod 2 ^ 63.
