   then (if Z.leb (hi1 + a_off (sx_a sx) + sx_m1 sx) lo then true else Z.leb hi (lo1 + a_off (sx_a sx))) else false) = true ->
  g1cBF bc sx (KImg lo hi) = [KImg lo hi].
