Fixpoint mk_flG (skip : sxi -> bool) (sis : list sxi) : list (sxi * list sxi) :=
  match sis with
  | si :: srest => if skip si then mk_flG skip srest else (si, srest) :: mk_flG skip srest
  | [] => []
  end.
