Lemma mk_flM_eq : forall bc b glo ghi gx gqj sis m, GMEMO bc glo ghi gx m ->
  mk_flM bc b glo ghi gx gqj true m sis = mk_flG (skipo5 bc b glo ghi gx gqj) sis /\
