(* [comment removed for export] *)
Definition ssvJ (s t : sxi) : bool :=
  match si_abj t, si_eabj s with
  | Some (A, B), Some (el, eh) => if PrimInt63.leb A el then true else PrimInt63.leb eh B
  | _, _ => false
  end.
(* [comment removed for export] *)
Definition skipS5 (bc : bctx) (s t : sxi) : bool :=
  if Pos.eqb (sx_bid (si_sx s)) (sx_bid (si_sx t)) then
    match si_iv s with Some (a, e) => nonov t a e | None => false end
  else if ssvJ s t then true
  else in_sides_num bc (sp_D (sx_sp (si_sx s))) (a_base (sx_a (si_sx t))) (a_off (sx_a (si_sx t))) (sx_m1 (si_sx t)).
(* [comment removed for export] *)
Definition dn_of (bc : bctx) (D : list (saddr * expr)) : list (saddr * option Z) := List.map (fun cm => (fst cm, xloB bc (snd cm))) D.
Fixpoint in_sides_numD (Dn : list (saddr * option Z)) (b : expr) (k n : Z) : bool :=
  match Dn with
  | [] => false
  | (c, xl) :: r =>
      if (if (if expr_eqb b (a_base c) then Z.leb (a_off c) k else false) then
            match xl with Some ml => Z.leb (k + n) (a_off c + ml) | None => false end
          else false) then true else in_sides_numD r b k n
  end.
Lemma in_sides_numD_eq : forall bc D b k n, in_sides_numD (dn_of bc D) b k n = in_sides_num bc D b k n.
