Definition skipS5D (bc : bctx) (s : sxi) : sxi -> bool :=
  let Dn := dn_of bc (sp_D (sx_sp (si_sx s))) in
  fun t =>
  if Pos.eqb (sx_bid (si_sx s)) (sx_bid (si_sx t)) then
    match si_iv s with Some (a, e) => nonov t a e | None => false end
  else if ssvJ s t then true
  else in_sides_numD Dn (a_base (sx_a (si_sx t))) (a_off (sx_a (si_sx t))) (sx_m1 (si_sx t)).
