Lemma grp_keepV : forall K' kk' m' sx, kdescr K' = Some (kb, kk', Some m') -> glo <= kk' -> kk' + m' <= ghi ->
  In sx sxs -> skipv5 bc bid glo ghi gx gqj (mk_sxi X sx) = true -> prG K' sx = PKeep.
