(* [comment removed for export] *)
Definition slackf (sl x : Z) : bool := if Z.leb 0 x then true else if Z.leb x (-4096) then false else Z.ltb (- sl) x.
Definition slackf2 (s1 s x : Z) : bool :=
  if Z.leb 0 x then true else if Z.leb x (-4096) then false else if Z.ltb (- s1) x then true else Z.ltb (- s) x.
Lemma slackf_mono : forall sl x y, x <= y -> slackf sl x = true -> slackf sl y = true.
Proof.
