Lemma sd_dead_false : forall bc b1 c m k n, sd_dead (mk_sidet bc b1 (mk_binf bc b1) c m) = true ->
  num_sub bc b1 k n c m = false /\ xinsideB bc b1 k (ELit n) (a_base c) (a_off c) m = false.
